input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var scopeRequest = input.query || input || {};
var scopeProjects = Array.isArray(scopeRequest.projects) ? scopeRequest.projects : (scopeRequest.projects ? [scopeRequest.projects] : []);
var projectKeys = [];
for (var si = 0; si < scopeProjects.length; si++) {
  var sp = scopeProjects[si];
  var sk = typeof sp === 'object' && sp !== null ? String(sp.jiraproject || '').trim() : '';
  if (sk && projectKeys.indexOf(sk) < 0) projectKeys.push(sk);
}
var hasIssueScope = 0;
for (var scopeIndex = 0; scopeIndex < scopeProjects.length; scopeIndex++) {
  var scopeProject = scopeProjects[scopeIndex];
  if (typeof scopeProject === 'string' && scopeProject.trim()) hasIssueScope = 1;
  if (scopeProject && typeof scopeProject === 'object' &&
      (String(scopeProject.projectname || '').trim() || String(scopeProject.jiraproject || '').trim())) hasIssueScope = 1;
}
if (projectKeys.length === 0) projectKeys = ['__NONE__'];

var q = input.query || input;
var projects = [];
if (Array.isArray(q.projects)) {
  projects = q.projects;
} else if (q.projects) {
  projects = [q.projects];
}

var excludeProjects = Array.isArray(q.excludeProjects) ? q.excludeProjects : [];

var projectnames = [];
var i, p, name;
for (i = 0; i < projects.length; i++) {
  p = projects[i];
  name = '';
  if (typeof p === 'string') {
    name = p.trim();
  } else if (typeof p === 'object' && p !== null) {
    name = (p.projectname || '').trim();
  }
  if (name) {
    projectnames.push(name);
  }
}

var from = Number(q.from) || 0;
var to = Number(q.to) || 0;

var userwhitelist = Array.isArray(q.userwhitelist) ? q.userwhitelist : [];

({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys,
  hasIssueScope: hasIssueScope,
  projectnames: projectnames.length > 0 ? projectnames : ['__no_filter__'],
  hasProjectFilter: projectnames.length > 0 ? 1 : 0,
  excludeProjects: excludeProjects.length > 0 ? excludeProjects : ['__no_filter__'],
  hasExcludeFilter: excludeProjects.length > 0 ? 1 : 0,
  from: from,
  to: to,
  userwhitelist: userwhitelist.length > 0 ? userwhitelist : ['__no_filter__'],
  hasUserFilter: userwhitelist.length > 0 ? 1 : 0
})

output_script:
var issueRows = results.issues || [];
var changelogRows = results.changelogs || [];

function calculateMedian(arr) {
  if (arr.length === 0) return 0;
  var sorted = arr.slice().sort(function(a, b) { return a - b; });
  var mid = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[mid - 1] + sorted[mid]) / 2;
  }
  return sorted[mid];
}

var result;

if (issueRows.length === 0) {
  result = { error: "No resolved issues found for this time period" };
} else {
  var issueChangelogs = {};
  var idx, cl, key;
  for (idx = 0; idx < changelogRows.length; idx++) {
    cl = changelogRows[idx];
    key = cl.issue_id;
    if (!issueChangelogs[key]) {
      issueChangelogs[key] = [];
    }
    issueChangelogs[key].push(cl);
  }

  var statusTimes = {};
  var i, issue, transitions, issueStatusTime, currentStatus, currentStart;
  var j, t, transitionTime, fromStatus, toStatus, hoursInStatus, finalHours;

  for (i = 0; i < issueRows.length; i++) {
    issue = issueRows[i];
    var createdAt = new Date(issue.created_date);
    var resolvedAt = new Date(issue.resolution_date);
    if (isNaN(createdAt.getTime()) || isNaN(resolvedAt.getTime())) continue;

    transitions = issueChangelogs[issue.id] || [];
    issueStatusTime = {};

    currentStatus = transitions.length > 0 ? transitions[0].original_from_value : null;
    currentStart = createdAt;

    if (!currentStatus) continue;

    for (j = 0; j < transitions.length; j++) {
      t = transitions[j];
      transitionTime = new Date(t.created_date);
      if (isNaN(transitionTime.getTime())) continue;

      fromStatus = t.original_from_value;
      toStatus = t.original_to_value;

      hoursInStatus = (transitionTime - currentStart) / (1000 * 60 * 60);
      if (hoursInStatus >= 0 && fromStatus) {
        if (!issueStatusTime[fromStatus]) issueStatusTime[fromStatus] = 0;
        issueStatusTime[fromStatus] += hoursInStatus;
      }

      currentStatus = toStatus;
      currentStart = transitionTime;
    }

    if (currentStatus) {
      finalHours = (resolvedAt - currentStart) / (1000 * 60 * 60);
      if (finalHours >= 0) {
        if (!issueStatusTime[currentStatus]) issueStatusTime[currentStatus] = 0;
        issueStatusTime[currentStatus] += finalHours;
      }
    }

    var statuses = Object.keys(issueStatusTime);
    for (j = 0; j < statuses.length; j++) {
      if (!statusTimes[statuses[j]]) statusTimes[statuses[j]] = [];
      statusTimes[statuses[j]].push(issueStatusTime[statuses[j]]);
    }
  }

  var statusCategory = {};
  for (idx = 0; idx < changelogRows.length; idx++) {
    cl = changelogRows[idx];
    if (cl.original_to_value && cl.to_value) {
      statusCategory[cl.original_to_value] = cl.to_value;
    }
    if (cl.original_from_value && cl.from_value) {
      statusCategory[cl.original_from_value] = cl.from_value;
    }
  }

  var doneNames = ['done', 'closed', 'resolved', 'complete', 'completed', 'obsolete', 'cancelled', "won't do", 'rejected'];
  var inProgressNames = ['in progress', 'in review', 'review', 'in development', 'developing', 'testing', 'code review'];
  var allStatuses = Object.keys(statusTimes);
  for (i = 0; i < allStatuses.length; i++) {
    var s = allStatuses[i];
    if (!statusCategory[s]) {
      var lower = s.toLowerCase();
      var found = false;
      for (j = 0; j < doneNames.length; j++) {
        if (lower === doneNames[j] || lower.indexOf(doneNames[j]) >= 0) {
          statusCategory[s] = 'DONE';
          found = true;
          break;
        }
      }
      if (!found) {
        for (j = 0; j < inProgressNames.length; j++) {
          if (lower === inProgressNames[j] || lower.indexOf(inProgressNames[j]) >= 0) {
            statusCategory[s] = 'IN_PROGRESS';
            found = true;
            break;
          }
        }
      }
      if (!found) {
        statusCategory[s] = 'TODO';
      }
    }
  }

  var statusOrder = Object.keys(statusTimes).sort(function(a, b) {
    return calculateMedian(statusTimes[b]) - calculateMedian(statusTimes[a]);
  });

  var preCommitmentStatuses = ['new', 'backlog', 'open', 'created', 'triage', 'groomed', 'refinement', 'to do', 'draft', 'planning', 'rejection pending'];

  var stages = [];
  for (i = 0; i < statusOrder.length; i++) {
    var statusName = statusOrder[i];
    var cat = statusCategory[statusName] || 'TODO';
    if (cat === 'DONE') continue;
    var lowerName = statusName.toLowerCase();
    var isPreCommitment = false;
    for (j = 0; j < preCommitmentStatuses.length; j++) {
      if (lowerName === preCommitmentStatuses[j]) {
        isPreCommitment = true;
        break;
      }
    }
    if (isPreCommitment) continue;
    stages.push({
      label: statusName,
      category: cat,
      value: calculateMedian(statusTimes[statusName])
    });
  }

  var issuesWithStageData = 0;
  for (i = 0; i < issueRows.length; i++) {
    transitions = issueChangelogs[issueRows[i].id] || [];
    if (transitions.length > 0 && transitions[0].original_from_value) {
      issuesWithStageData = issuesWithStageData + 1;
    }
  }
  var totalResolved = issueRows.length;
  var hasMixedSources = issuesWithStageData < totalResolved;

  result = {
    type: "stagedoughnut",
    label: "Issue Stage Breakdown",
    description: "Shows where resolved issues spend their time across active workflow stages. Each slice represents a Jira status — its size shows the median time in that stage relative to the others. Pre-commitment stages (New, Backlog, Groomed, Refinement, Draft, Planning, Rejection Pending) and terminal statuses (Done, Closed) are excluded.",
    lastupdate: new Date().getTime(),
    data: {
      stages: stages,
      resolvedCount: hasMixedSources ? issuesWithStageData : totalResolved
    }
  };

  if (hasMixedSources) {
    var githubCount = totalResolved - issuesWithStageData;
    result.data.totalResolvedCount = totalResolved;
    result.data.note = issuesWithStageData + " of " + totalResolved + " resolved issues are from Jira and have workflow stage data. " + githubCount + " GitHub issue" + (githubCount !== 1 ? "s are" : " is") + " not included as they lack workflow transitions.";
  }
}

